/** The wall levels the top bar offers, per cent; 0 is "off", the black mask. The same steps as the import summary. */
export const LED_BAR_LEVELS = [0, 10, 25, 50, 100] as const;

/**
 * The desk's blackout does not reach the walls; the control says so where the user sets them, and that the content
 * on the walls is the desk's (the sentence of the layer list's note, `LED_GENERATED`).
 */
export const LED_BAR_TIP =
  'Level of the LED walls. B.O. is a lighting blackout: LED walls are video, they stay on, and only this control sets them. LED content is generated by the desk; it is not in the file.';

/** What the top bar's LED control drives: the level now, and how to set it. */
export interface LedBarControl {
  readonly level: number;
  readonly set: (percent: number) => void;
}

interface LedBar {
  readonly group: HTMLElement;
  readonly select: HTMLSelectElement;
}

/**
 * The LED group of the top bar, made beside the Haze group the first time a stage needs it: the markup of the top
 * bar stays that of the built-in desk, which has no LED walls. Nothing where no page stands (a unit test of the app
 * wiring) or the top bar is not built.
 */
function ledBar(make: boolean): LedBar | undefined {
  if (typeof document === 'undefined') return undefined;
  const group = document.getElementById('ledGroup');
  const select = document.getElementById('ledWalls');
  if (group && select instanceof HTMLSelectElement) return { group, select };
  const haze = document.getElementById('haze')?.parentElement;
  if (!make || !haze) return undefined;
  const made = { group: document.createElement('div'), select: document.createElement('select') };
  made.group.className = 'tbg';
  made.group.id = 'ledGroup';
  made.select.id = 'ledWalls';
  made.select.title = LED_BAR_TIP;
  const label = document.createElement('label');
  label.textContent = 'LED';
  for (const percent of LED_BAR_LEVELS) {
    const option = document.createElement('option');
    option.value = String(percent);
    option.textContent = percent === 0 ? 'off' : `${percent} %`;
    made.select.appendChild(option);
  }
  made.group.append(label, made.select);
  haze.after(made.group);
  return made;
}

/**
 * Shows the top bar's LED level for an MVR stage with LED walls, at the level the walls have now, or hides it
 * (`undefined`): a built-in stage, or a file without an LED surface, has nothing to set. The level is view state like
 * the House slider beside it: it is not saved with the show, and an import starts at the default.
 */
export function showLedBar(control: LedBarControl | undefined): void {
  const bar = ledBar(control !== undefined);
  if (!bar) return;
  bar.group.style.display = control ? '' : 'none';
  bar.select.onchange = control ? () => control.set(Number(bar.select.value)) : null;
  if (control) bar.select.value = String(control.level);
}

/** Moves the top bar's LED level to `percent`, after the import summary set it. */
export function syncLedBar(percent: number): void {
  const bar = ledBar(false);
  if (bar) bar.select.value = String(percent);
}
